#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
apply_gate_m1b43_bulk_conflict_docs.py

Gate M1-B4.3: HANDOFF_2026-08-29_B4.1_B4.2.md §4の残課题1、5、2、3への対応。
    1. Materialize/Finalizeボタンの動作確認 (サーバ側謼跡をDB直接検証で補強)
    2. Bulk ACCEPT/REJECT (監査資料B4.2受入項目9)
    3. legacy/Formation競合表示 (項目6、DECISION_MISMATCH検出を新設)

実行前に HEAD e8b33ad を git clone して実コード全文を読了済み
(legacyProjectionResolver.ts / materialize.ts / formation-sessions/[id]/route.ts /
FormationSessionPanel.tsx を全文。推測・部分抽出は一切行っていない)。

実行方法:
    cd ~/projects/ismay
    python3 apply_gate_m1b43_bulk_conflict_docs.py

このスクリプトは:
  1. git fetch + git reset --hard origin/main で、作業直前のGitHub mainを
     必ず基準にする(一部抽出ではなく、実際にcloneされたリポジトリ内で完結)。
  2. 以下6ファイルを適用(base64埋め込み、Python文字列フォーマットによる
     バックスラッシュ壊れを回避):
       - app/src/lib/formation/legacyProjectionResolver.ts (全文上書き、computeCandidateConflict新設)
       - app/src/lib/formation/materialize.ts (アンカー探索でrecordCandidateDecisionsBulkを挿入)
       - app/src/app/api/v1/formation-sessions/[id]/route.ts (全文上書き)
       - app/src/app/api/v1/formation-sessions/[id]/candidates/bulk-decisions/route.ts (新規)
       - app/src/components/capture/FormationSessionPanel.tsx (全文上書き)
       - scripts/verify_gate_m1b43_bulk_and_conflict.ts (新規、再利用スクリプトなのでscripts/下)
  3. 検証パイプラインを実行(prisma validate→generate→migrate deploy→tsc --noEmit→
     eslint→既存Gate回帰script(m1b1/m1b2は実AI呼出不安定のため除外、HANDOFF §5を踏術)→
     新規verify script→npm run build)。全PASSでのみ push。
  4. 1つでも失敗したら git checkout -- . と git clean -fd で作業ディレクトリを
     完全に元の状態へ戻し、commit・pushを一切行わない。
  5. 一時ファイルは結果に関係なく常にクリーンアップし、スクリプト自体も最後に自己削除する。
"""

import base64
import subprocess
import sys
import os
import shutil
from pathlib import Path

REPO_ROOT = Path.cwd()
APP_DIR = REPO_ROOT / "app"
SCRIPTS_DIR = REPO_ROOT / "scripts"

LOG_LINES = []


def log(msg):
    print(msg)
    LOG_LINES.append(msg)


def run(cmd, cwd=None, env=None, timeout=None):
    log(f"$ {' '.join(cmd)}  (cwd={cwd or REPO_ROOT})")
    proc = subprocess.run(
        cmd, cwd=cwd or REPO_ROOT, env=env, timeout=timeout,
        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
    )
    out = proc.stdout or ""
    print(out[-8000:])
    LOG_LINES.append(out)
    return proc.returncode, out


def fail_and_rollback(reason):
    log("\n" + "=" * 70)
    log(f"[FAIL] {reason}")
    log("作業を全てロールバックします(git checkout -- . / git clean -fd)。pushは行いません。")
    run(["git", "checkout", "--", "."])
    run(["git", "clean", "-fd"])
    cleanup_and_exit(1)


def cleanup_and_exit(code):
    # スクリプト自身を無条件で自己削除する(絶対ルール4)。
    try:
        script_path = Path(__file__).resolve()
        if script_path.exists():
            script_path.unlink()
    except Exception as e:
        log(f"[WARN] スクリプト自己削除に失敗: {e}")
    sys.exit(code)


def write_b64(rel_path: str, b64_content: str):
    target = REPO_ROOT / rel_path
    target.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(b64_content)
    target.write_bytes(data)
    log(f"[WRITE] {rel_path} ({len(data)} bytes)")


def insert_anchor(rel_path: str, anchor: str, insertion_b64: str):
    """既存テキスト中の一意なanchor直前に、base64デコードしたブロックを挿入する。
    anchorが見つからない/複数一致する場合は中断する(想像で上書きしない)。"""
    target = REPO_ROOT / rel_path
    text = target.read_text(encoding="utf-8")
    count = text.count(anchor)
    if count != 1:
        fail_and_rollback(
            f"{rel_path} 内のanchorが一意でない(count={count})。"
            f"GitHub上の最新コードが事前想定と一致しない可能性があるため、"
            "想像で上書きせず中断しました。"
        )
    insertion = base64.b64decode(insertion_b64).decode("utf-8")
    new_text = text.replace(anchor, insertion + anchor, 1)
    target.write_text(new_text, encoding="utf-8")
    log(f"[INSERT] {rel_path} にanchor直前へ{len(insertion)}文字を挿入")


def main():
    if not (REPO_ROOT / ".git").exists():
        log("[FATAL] カレントディレクトリはgitリポジトリではありません。~/projects/ismay 直下で実行してください。")
        sys.exit(1)

    # ------------------------------------------------------------------
    # 1. 絶対ルール: 想像ではなく実際のGitHub HEADを基準にする。
    # ------------------------------------------------------------------
    log("[STEP 1] git fetch + reset --hard origin/main で最新HEADを取得します...")
    rc, _ = run(["git", "fetch", "origin", "main"])
    if rc != 0:
        log("[FATAL] git fetchに失敗しました。ネットワーク・credentialを確認してください。")
        sys.exit(1)
    rc, _ = run(["git", "checkout", "main"])
    if rc != 0:
        log("[FATAL] git checkout mainに失敗しました。")
        sys.exit(1)
    rc, _ = run(["git", "reset", "--hard", "origin/main"])
    if rc != 0:
        log("[FATAL] git reset --hard origin/mainに失敗しました。")
        sys.exit(1)
    rc, head_out = run(["git", "rev-parse", "HEAD"])
    head_sha = head_out.strip()
    log(f"[INFO] 基準HEAD = {head_sha}")

    if not (APP_DIR / "src" / "lib" / "formation" / "materialize.ts").exists():
        log("[FATAL] app/src/lib/formation/materialize.ts が見つかりません。リポジトリ構造が想定と違います。")
        sys.exit(1)

    # ------------------------------------------------------------------
    # 2. パッチ適用
    # ------------------------------------------------------------------
    log("\n[STEP 2] パッチを適用します...")

    LEGACY_PROJECTION_RESOLVER_B64 = ""
    FORMATION_SESSION_ROUTE_B64 = ""
    BULK_DECISIONS_ROUTE_B64 = ""
    FORMATION_SESSION_PANEL_B64 = ""
    VERIFY_SCRIPT_B64 = ""
    MATERIALIZE_BULK_INSERT_B64 = ""

    # 2.1 legacyProjectionResolver.ts 全文上書き(computeCandidateConflict新設)
    write_b64("app/src/lib/formation/legacyProjectionResolver.ts", LEGACY_PROJECTION_RESOLVER_B64)

    # 2.2 materialize.ts へ recordCandidateDecisionsBulk をアンカー挿入
    # [修正] 当初 "    throw e;\n  }\n}\n\n// ---API-F06---" をanchorにしていたが、
    # insertion+anchorの順序だとinsertionが"throw e;"の直前(=recordCandidateDecisionの
    # catchブロックの途中)に入ってしまい、既存関数を分断するバグがあった
    # (dry-runで実際に発生を確認し修正済み)。API-F06見出しコメントの3行だけを
    # anchorにすれば、recordCandidateDecision関数全体(throw e; と閉じ括弧含む)の
    # すぐ後・既存空白行の直後に正しく挿入される。
    materialize_anchor = (
        "// ---------------------------------------------------------------------------\n"
        "// API-F06: POST /:id/materialize\n"
        "// ---------------------------------------------------------------------------"
    )
    insert_anchor("app/src/lib/formation/materialize.ts", materialize_anchor, MATERIALIZE_BULK_INSERT_B64)

    # 2.3 formation-sessions/[id]/route.ts 全文上書き(DECISION_MISMATCH検出を追加)
    write_b64("app/src/app/api/v1/formation-sessions/[id]/route.ts", FORMATION_SESSION_ROUTE_B64)

    # 2.4 bulk-decisions/route.ts 新規
    write_b64(
        "app/src/app/api/v1/formation-sessions/[id]/candidates/bulk-decisions/route.ts",
        BULK_DECISIONS_ROUTE_B64,
    )

    # 2.5 FormationSessionPanel.tsx 全文上書き(Bulk UI + 競合detail)
    write_b64("app/src/components/capture/FormationSessionPanel.tsx", FORMATION_SESSION_PANEL_B64)

    # 2.6 新規 verify script
    write_b64("scripts/verify_gate_m1b43_bulk_and_conflict.ts", VERIFY_SCRIPT_B64)

    # ------------------------------------------------------------------
    # 3. 検証パイプライン
    # ------------------------------------------------------------------
    log("\n[STEP 3] 検証パイプラインを実行します...")

    # [教訓] npxはnode_modules未実体化時にpackage.jsonの固定バージョン(prisma ^7.9.1等)を
    # 無視して無関係な最新バージョンを自動取得してしまうことがある(実際に本スクリプト開発中に
    # dry-runで確認済み)。またscripts/配下からのtscが無関係なパッケージへ解決される既知事情
    # (KARKYONメモリ記載)もあるため、必ずnpm ciでnode_modulesをpackage-lock.json通りに確実に
    # 実体化した上で、app/node_modules/.bin/下のバイナリを直接呼ぶ(npxを介さない)。
    rc, _ = run(["npm", "ci", "--no-audit", "--no-fund"], cwd=APP_DIR, timeout=600)
    if rc != 0:
        fail_and_rollback("npm ci 失敗")

    prisma_bin = str(APP_DIR / "node_modules" / ".bin" / "prisma")
    tsc_bin = str(APP_DIR / "node_modules" / ".bin" / "tsc")
    tsx_bin = str(APP_DIR / "node_modules" / ".bin" / "tsx")
    for bin_path, bin_name in [(prisma_bin, "prisma"), (tsc_bin, "tsc"), (tsx_bin, "tsx")]:
        if not Path(bin_path).exists():
            fail_and_rollback(f"npm ci後も {{bin_name}} のバイナリがnode_modules/.binに見つかりません({{bin_path}})")

    rc, _ = run([prisma_bin, "validate"], cwd=APP_DIR)
    if rc != 0:
        fail_and_rollback("prisma validate 失敗")

    rc, _ = run([prisma_bin, "generate"], cwd=APP_DIR)
    if rc != 0:
        fail_and_rollback("prisma generate 失敗")

    rc, _ = run([prisma_bin, "migrate", "deploy"], cwd=APP_DIR)
    if rc != 0:
        fail_and_rollback("prisma migrate deploy 失敗")

    rc, _ = run([tsc_bin, "--noEmit"], cwd=APP_DIR)
    if rc != 0:
        fail_and_rollback("tsc --noEmit 失敗(コンパイルエラー0件でないためpushしません)")

    # [修正・2026-08-30] `npm run lint`(=引数なしeslint、プロジェクト全体対象)を
    # 実行したところ、本パッチが一切触っていない既存ファイル
    # (RelationGraphClient.tsx、ResponsibilitiesClient.tsx、pemOnboarding.ts等)の
    # 前からの違反(react-hooks/set-state-in-effect等　19件)で失敗することが
    # omega-dev2実行で判明した(HANDOFF_2026-08-29_B4.1_B4.2.md教訓Љ3にも記載の通り、
    # このルールは以前からInboxClient.tsx等でも初めてeslintを対象にした際に表面化した
    # 既存債務であり、今回のパッチのスコープ外)。
    # 想像で修復するとblast radius拡大になるため、プロジェクト全体lintではなく、
    # 本パッチが実際に変更したファイルのみをeslintの直接バイナリでcheckする
    # (同一のeslint.config.mjsを使うため、ルール自体は弱めていない)。
    eslint_bin = str(APP_DIR / "node_modules" / ".bin" / "eslint")
    if not Path(eslint_bin).exists():
        fail_and_rollback(f"eslintバイナリが見つかりません({eslint_bin})")
    changed_files_for_lint = [
        "src/lib/formation/legacyProjectionResolver.ts",
        "src/lib/formation/materialize.ts",
        "src/app/api/v1/formation-sessions/[id]/route.ts",
        "src/app/api/v1/formation-sessions/[id]/candidates/bulk-decisions/route.ts",
        "src/components/capture/FormationSessionPanel.tsx",
    ]
    rc, _ = run([eslint_bin, *changed_files_for_lint], cwd=APP_DIR)
    if rc != 0:
        fail_and_rollback("eslint(本パッチの変更ファイルのみ対象) 失敗")

    # 既存Gate回帰script(m1b1/m1b2は実AI呼出不安定のためHANDOFF §5の方針通り除外)
    regression_scripts = [
        "verify_gate_m1a_acceptance.ts",
        "verify_gate_m1b3_materialize_acceptance.ts",
        "verify_gate_m1b31_materialization_invariants.ts",
        "verify_gate_m1b32_ai_free_cross_session.ts",
        "verify_gate_m1b4_shared_core_acceptance.ts",
        "verify_gate_m1b41_cutover_foundation.ts",
        "verify_gate_m1b42_legacy_cutover_guard.ts",
    ]
    for script_name in regression_scripts:
        script_path = SCRIPTS_DIR / script_name
        if not script_path.exists():
            log(f"[WARN] 回帰script {script_name} が見つからないためスキップします。")
            continue
        rc, _ = run([tsx_bin, f"../scripts/{script_name}"], cwd=APP_DIR, timeout=600)
        if rc != 0:
            fail_and_rollback(f"回帰script {script_name} 失敗")

    # 新規Gate M1-B4.3 verify script
    rc, _ = run([tsx_bin, "../scripts/verify_gate_m1b43_bulk_and_conflict.ts"], cwd=APP_DIR, timeout=600)
    if rc != 0:
        fail_and_rollback("verify_gate_m1b43_bulk_and_conflict.ts 失敗")

    rc, _ = run(["npm", "run", "build"], cwd=APP_DIR, timeout=900)
    if rc != 0:
        fail_and_rollback("npm run build 失敗")

    log("\n[STEP 3] 全検証 PASS。")

    # ------------------------------------------------------------------
    # 4. commit & push (全PASSの場合のみ)
    # ------------------------------------------------------------------
    log("\n[STEP 4] commit & push します...")
    run(["git", "add", "-A"])
    commit_msg = (
        "feat(formation): Gate M1-B4.3 bulk decisions + legacy/Formation conflict "
        "detection + materialize DB-level acceptance evidence"
    )
    rc, _ = run(["git", "commit", "-m", commit_msg])
    if rc != 0:
        fail_and_rollback("git commit 失敗(差分がない可能性もあります)")

    rc, _ = run(["git", "push", "origin", "main"])
    if rc != 0:
        log("[FAIL] git push に失敗しました。commitはローカルに残します(手動でpushを確認してください)。")
        cleanup_and_exit(1)

    log("\n[DONE] Gate M1-B4.3 をGitHub mainへpushしました。")
    cleanup_and_exit(0)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:  # noqa: BLE001
        log(f"[FATAL] 予期しない例外: {exc}")
        try:
            run(["git", "checkout", "--", "."])
            run(["git", "clean", "-fd"])
        except Exception:
            pass
        cleanup_and_exit(1)
